package org.apache.dubbo.registry.client;

import org.apache.dubbo.common.URL;
import org.apache.dubbo.metadata.MetadataInfo;
import org.apache.dubbo.registry.NotifyListener;

import java.util.Collections;
import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Tests for {@link ServiceDiscovery} default methods.
 */
class ServiceDiscoveryTest {

    /**
     * A minimal implementation of ServiceDiscovery that does NOT override getUrl().
     * This means getUrl() returns null (the default), and getDelay() should handle
     * this gracefully instead of throwing NullPointerException.
     */
    private static class MinimalServiceDiscovery implements ServiceDiscovery {
        @Override
        public void register() throws RuntimeException {}

        @Override
        public void update() throws RuntimeException {}

        @Override
        public void unregister() throws RuntimeException {}

        @Override
        public Set<String> getServices() {
            return Collections.emptySet();
        }

        @Override
        public List<ServiceInstance> getInstances(String serviceName) throws NullPointerException {
            return Collections.emptyList();
        }

        @Override
        public ServiceInstance getLocalInstance() {
            return null;
        }

        @Override
        public MetadataInfo getLocalMetadata() {
            return null;
        }

        @Override
        public MetadataInfo getRemoteMetadata(String revision) {
            return null;
        }

        @Override
        public MetadataInfo getRemoteMetadata(String revision, List<ServiceInstance> instances) {
            return null;
        }

        @Override
        public void destroy() throws Exception {}

        @Override
        public boolean isDestroy() {
            return false;
        }

        @Override
        public void register(URL url) {}

        @Override
        public void unregister(URL url) {}

        @Override
        public void subscribe(URL url, NotifyListener listener) {}

        @Override
        public void unsubscribe(URL url, NotifyListener listener) {}

        @Override
        public List<URL> lookup(URL url) {
            return Collections.emptyList();
        }
    }

    /**
     * Test that getDelay() does not throw NullPointerException when getUrl() returns null.
     * Since getUrl() returns null by default, getDelay() should return the default delay value (5000).
     */
    @Test
    void testGetDelayWithNullUrl() {
        ServiceDiscovery discovery = new MinimalServiceDiscovery();

        // getUrl() returns null by default
        Assertions.assertNull(discovery.getUrl());

        // getDelay() should handle null URL gracefully and return default value 5000,
        // NOT throw NullPointerException
        long delay = discovery.getDelay();
        Assertions.assertEquals(5000, delay);
    }
}

