        Assertions.assertEquals(expectedResult, bitList);
    }

    @Test
    void testListIterator6() {
        List<String> list = Arrays.asList("A", "B", "C", "D", "E");
        BitList<String> bitList = new BitList<>(list);
        bitList.addAll(Arrays.asList("F", "G", "H", "I"));
