        // Remove all elements so cardinality becomes 0
        bitList.removeAll(list);
        Assertions.assertTrue(bitList.isEmpty());
        Assertions.assertEquals(0, bitList.size());

        // randomSelectOne on empty BitList should return null, not throw ArithmeticException
        Assertions.assertNull(bitList.randomSelectOne());
    }
