        bitList1.removeAll(list);
        Assertions.assertEquals(0, bitList1.size());

        bitList1.addAll(bitList2);

        Assertions.assertEquals(3, bitList1.size());
        Assertions.assertFalse(bitList1.hasMoreElementInTailList());

        bitList1.addAll(bitList2);

        Assertions.assertEquals(3, bitList1.size());
    }

    @Test
