package org.apache.dubbo.common.extension.support;

import org.apache.dubbo.common.extension.Activate;
import org.apache.dubbo.rpc.model.ApplicationModel;

import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Test that ActivateComparator obeys the Comparator contract.
 * When two classes have the same order AND the same simple name,
 * compare(o1, o2) should return 0 (as required by the Comparator contract),
 * not -1.
 */
class ActivateComparatorComparatorContractTest {

    /**
     * Inner class with simple name "Order0Filter1" — deliberately colliding
     * with the existing top-level Order0Filter1 simple name.
     * Both have @Activate with default order 0 and no before/after.
     */
    @Activate
    static class Order0Filter1 {
        // same simple name as org.apache.dubbo.common.extension.support.Order0Filter1
    }

    @Test
    void testCompareReturnsZeroWhenOrderAndSimpleNameAreEqual() {
        ActivateComparator comparator =
                new ActivateComparator(ApplicationModel.defaultModel().getExtensionDirector());

        // Two DIFFERENT Class objects with the SAME simple name and the SAME order
        Class<?> inner = Order0Filter1.class;
        Class<?> topLevel = org.apache.dubbo.common.extension.support.Order0Filter1.class;

        Assertions.assertNotSame(inner, topLevel, "Should be different classes");
        Assertions.assertEquals(inner.getSimpleName(), topLevel.getSimpleName(),
                "Simple names must be the same for this test");

        // Comparator contract: compare(a, b) == 0 when a and b are considered equal by the comparator.
        // With same order and same simple name, they should be considered equal → return 0.
        int result = comparator.compare(inner, topLevel);
        Assertions.assertEquals(0, result,
                "Comparator must return 0 when both order and simple name are equal, "
                + "but returned " + result
                + " (violates Comparator contract — TreeSet would lose entries)");
    }

    @Test
    void testCompareAntiSymmetryWhenSimpleNameEqual() {
        ActivateComparator comparator =
                new ActivateComparator(ApplicationModel.defaultModel().getExtensionDirector());

        Class<?> inner = Order0Filter1.class;
        Class<?> topLevel = org.apache.dubbo.common.extension.support.Order0Filter1.class;

        // Comparator contract: compare(a, b) == -compare(b, a)
        int a = comparator.compare(inner, topLevel);
        int b = comparator.compare(topLevel, inner);

        Assertions.assertEquals(-a, b,
                "Comparator must be antisymmetric: compare(a,b) == -compare(b,a). "
                + "Got compare(inner, topLevel) = " + a
                + ", compare(topLevel, inner) = " + b);
    }

    @Test
    void testTreeSetRetainsBothEntriesWhenSimpleNameEqual() {
        ActivateComparator comparator =
                new ActivateComparator(ApplicationModel.defaultModel().getExtensionDirector());

        Class<?> inner = Order0Filter1.class;
        Class<?> topLevel = org.apache.dubbo.common.extension.support.Order0Filter1.class;

        TreeSet<Class<?>> treeSet = new TreeSet<>(comparator);
        treeSet.add(inner);
        treeSet.add(topLevel);

        // With correct comparator (returns 0 when same order+name), TreeSet treats them as equal
        // and keeps only one. This test verifies the comparator's behavior is consistent.
        // The key point: if compare returns -1 for both directions, TreeSet behavior is undefined.
        // If compare returns 0 for both directions (correct), TreeSet keeps exactly one.
        // This test mainly confirms the Comparator contract is not violated in a way
        // that causes unpredictable behavior.
        int a = comparator.compare(inner, topLevel);
        int b = comparator.compare(topLevel, inner);
        if (a == 0 || b == 0) {
            // When equal, TreeSet size should be 1
            Assertions.assertEquals(1, treeSet.size());
        } else {
            // When not equal, TreeSet size should be 2 (no contract violation)
            Assertions.assertEquals(2, treeSet.size());
        }
    }
}

