class ListDoubleMatchTest {

    @Test
    void isMatchWithNullOneof() {
        ListDoubleMatch listDoubleMatch = new ListDoubleMatch();
        // oneof is null by default; isMatch should return false, not throw NPE
        assertFalse(listDoubleMatch.isMatch(10.0));
    }

