        oneof.add(doubleMatch2);

        listDoubleMatch.setOneof(oneof);

        assertTrue(listDoubleMatch.isMatch(10.0));
        assertTrue(listDoubleMatch.isMatch(11.0));
        assertFalse(listDoubleMatch.isMatch(12.0));
    }
}

