        assertFalse(NetUtils.isIPV6URLStdFormat("192.168.1.1"));
        assertFalse(NetUtils.isIPV6URLStdFormat("localhost"));
        assertFalse(NetUtils.isIPV6URLStdFormat("[]"));
        assertFalse(NetUtils.isIPV6URLStdFormat("127.0.0.1:8080"));
    }

